function t(s){return state.lang==='ar'?(ar[s]||s):s;}
function icon(name){const paths={home:'M3 10l9-7 9 7M5 9v11h5v-7h4v7h5V9',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',wallet:'M3 7h18v13H3zM3 7V4h15v3M16 11h5v5h-5z',chart:'M4 20V9M10 20V4M16 20v-8M22 20V7',book:'M12 5c-3-2-7-2-10-1v15c4-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1v15',briefcase:'M3 7h18v14H3zM8 7V3h8v4M3 12c6 3 12 3 18 0M12 12v4',folder:'M2 6h8l2 3h10v12H2z',check:'M5 12l4 4L20 5M20 13v7H3V3h12',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',star:'M12 2l3 6.5 7 .9-5 5 1.2 7L12 18l-6.2 3.4L7 14.4l-5-5 7-.9z',file:'M14 2H4v20h16V8zM14 2v6h6M8 13h8M8 17h6',exit:'M9 21H3V3h6M8 12h14M17 7l5 5-5 5',calendar:'M3 5h18v16H3zM3 10h18M7 3v5M17 3v5',spark:'M12 2l2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',down:'M6 9l6 6 6-6',download:'M12 3v12M7 10l5 5 5-5M3 15v6h18v-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l-1 3-3 1-2 4 2 2-1 4 4 3 3-1 3 2 4-3v-3l3-2-1-5-3-1-1-4z',close:'M6 6l12 12M6 18L18 6',menu:'M3 6h18M3 12h18M3 18h18',edit:'M16 3l5 5L8 21H3v-5z',message:'M3 3h18v14H8l-5 4z',globe:'M2 12h20M12 2c6 5 6 15 0 20-6-5-6-15 0-20M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',copy:'M8 8h13v13H8zM16 8V3H3v13h5'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;}
function button(label,action,extra='',cls=''){return `<button class="button ${cls}" data-action="${action}" ${extra}>${esc(t(label))}</button>`;}
function badge(value){const type=/Reject|Overdue|Urgent|Archived/.test(value)?'red':/Pending|Draft|Proposed|High|To do|Notice/.test(value)?'amber':/progress|Interview|Submitted|Screening/.test(value)?'blue':'';return `<span class="badge ${type}">${esc(t(value))}</span>`;}
function initials(name){return String(name||'?').split(' ').slice(0,2).map(n=>n[0]).join('');}
function avatar(name,i=0){return `<span class="avatar ${i%3===1?'peach':i%3===2?'lilac':''}">${esc(initials(name))}</span>`;}
function person(id){return state.boot.lookups.employees.find(e=>e.id===Number(id))?.name||'#'+id;}
function lookup(type,id){return (state.boot.lookups[type]||[]).find(r=>r.id===Number(id))?.name||(state.boot.lookups[type]||[]).find(r=>r.id===Number(id))?.title||'—';}
function currency(cents){return new Intl.NumberFormat(state.lang==='ar'?'ar-EG':'en-GB',{style:'currency',currency:state.boot?.settings.currency||'EGP',maximumFractionDigits:0}).format(Number(cents||0)/100);}
function day(value,opts={day:'numeric',month:'short',year:'numeric'}){return value?new Intl.DateTimeFormat(state.lang==='ar'?'ar-EG':'en-GB',opts).format(new Date(value.length===10?value+'T12:00':value)):'—';}
function todayISO(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
async function api(path,method='GET',data){const response=await fetch('/api'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},credentials:'same-origin',body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok){if(response.status===401&&!path.includes('login')){state.boot=null;renderLogin();}throw new Error(result.error||'Request failed');}return result;}
function toast(message,error=false){$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${esc(message)}</div>`;setTimeout(()=>$('#toast-root').innerHTML='',6000);}
function setLanguage(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';localStorage.setItem('northstar-language',state.lang);}
function loading(){return `<div class="loader"><span class="spinner"></span><div>${t('Loading your workspace…')}</div></div>`;}
function empty(message='No records yet'){return `<div class="empty">${icon('folder')}<h3>${t(message)}</h3><p>${t(message==='No records yet'?'Create your first record to get started.':'Try a different search.')}</p></div>`;}
function renderLogin(){setLanguage();$('#app').innerHTML=`<main class="login"><section class="login-story"><div class="brand"><span class="brand-mark">✳</span><span>northstar<small>PEOPLE & POSSIBILITIES</small></span></div><h1>${t('Your people. Your potential.')}</h1><p>${t('A thoughtful workspace for the people who move your company forward.')}</p></section><section class="login-form-wrap"><button class="button login-language" data-action="language">${icon('globe')} ${state.lang==='en'?'العربية':'English'}</button><form class="login-form" id="login-form"><div class="eyebrow">NORTHSTAR PEOPLE</div><h2>${t('Welcome back')}</h2><p class="muted small-text">${t('Sign in to your workspace')}</p><div class="field"><label for="email">${t('Email address')}</label><input class="field-input" id="email" name="email" type="email" autocomplete="username" required value="hr@demo.local"></div><div class="field"><label for="password">${t('Password')}</label><input class="field-input" id="password" name="password" type="password" autocomplete="current-password" required value="Demo2026!"></div><div id="login-error" role="alert"></div><button class="button primary" type="submit">${t('Sign in')} ${icon('arrow')}</button><div class="demo-accounts"><p>${t('Development demo accounts')} · Demo2026!</p><div class="demo-chips">${[['owner','Company Owner'],['hr','HR Administrator'],['manager','Department Manager'],['leader','Team Leader'],['nora','Employee']].map(([email,label])=>`<button type="button" class="demo-chip" data-action="demo-account" data-email="${email}@demo.local">${t(label)}</button>`).join('')}</div><p>${t('Use a role below to explore the fictional workspace.')}</p></div></form></section></main>`;$('#login-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{await api('/login','POST',Object.fromEntries(new FormData(e.target)));await boot();}catch(error){$('#login-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`;}finally{b.disabled=false;}};}
function allowed(page){const role=state.boot.user.role;if(['jobs','candidates','interviews'].includes(page))return ['hr','manager','leader'].includes(role);if(page==='settings')return role==='hr';return true;}
const NAV=[['OVERVIEW',[['dashboard','My dashboard','grid'],['announcements','Company home','home']]],['PEOPLE & OPERATIONS',[['employees','People','users'],['leave_requests','Attendance & leave','clock'],['payroll','Payroll','wallet'],['jobs','Recruitment','briefcase'],['contracts','Records & contracts','folder'],['checklists','Onboarding','check'],['resignations','Retention & offboarding','exit']]],['GROWTH & CULTURE',[['kpis','Performance','chart'],['reports','Monthly reports','file'],['learning_plans','Learning & growth','book'],['tasks','Tasks & workload','grid'],['surveys','Engagement','heart'],['recognition','Recognition','star'],['cases','Complaints & suggestions','message'],['articles','Knowledge base','book']]],['INTELLIGENCE',[['assistant','AI assistant','spark'],['settings','Settings','settings']]]];
function pageLabel(){return ({dashboard:'My dashboard',assistant:'AI assistant',cases:'Complaints & suggestions',settings:'Settings'})[state.page]||state.boot.catalog[state.page]?.label||'Workspace';}
function renderShell(){setLanguage();const u=state.boot.user;$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark">✳</span><span>northstar<small>PEOPLE & POSSIBILITIES</small></span></div><div class="nav-scroll">${NAV.map(([label,items])=>`<div class="nav-label">${t(label)}</div>${items.filter(([page])=>allowed(page)).map(([page,label,ic])=>`<button class="nav-button ${state.page===page?'active':''}" data-action="navigate" data-page="${page}">${icon(ic)}<span>${t(label)}</span></button>`).join('')}`).join('')}</div><div class="sidebar-bottom"><button class="nav-button" data-action="logout">${icon('exit')}${t('Sign out')}</button><div class="demo-label">● ${t('Fictional demo workspace')}<br>${state.boot.settings.ai_mode==='live'?t('Live AI'):t('Demo AI')} · Northstar Studio</div></div></aside><main class="main"><header class="topbar"><div class="row"><button class="icon-button mobile-menu" data-action="mobile-menu" aria-label="Menu">${icon('menu')}</button><div class="breadcrumb"><span>${t('Workspace')}</span>${icon('chevron')}<strong>${t(pageLabel())}</strong></div></div><div class="top-tools"><form id="global-search" class="search-box">${icon('search')}<input name="search" aria-label="${t('Search knowledge…')}" placeholder="${t('Search knowledge…')}"><span class="key">↵</span></form><button class="icon-button" data-action="language" aria-label="Change language">${icon('globe')}</button><button class="icon-button" data-action="notifications" aria-label="${t('Notifications')}">${icon('bell')}</button><div class="profile">${avatar(u.name)}<div><div class="profile-name">${esc(u.name)}</div><div class="profile-role">${t(({owner:'Company Owner',hr:'HR Administrator',manager:'Department Manager',leader:'Team Leader',employee:'Employee'})[u.role])}</div></div></div></div></header><div class="content" id="content">${loading()}</div></main></div>`;$('#global-search').onsubmit=e=>{e.preventDefault();const q=new FormData(e.target).get('search');navigate('articles').then(()=>{const input=$('#record-search');if(input){input.value=q;filterRecords(q);}});};}
function heading(subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${t('A better day at work.').toUpperCase()}</div><h1>${t(pageLabel())}</h1><p class="subtitle">${esc(t(subtitle))}</p></div><div class="actions">${actions}</div></div>`;}
function footer(){return `<footer class="page-footer"><span>© ${new Date().getFullYear()} Northstar People</span><span>${t('Built for people. Designed for possibility.')}</span></footer>`;}
async function boot(){state.boot=await api('/bootstrap');state.page=allowed(state.page)?state.page:'dashboard';renderShell();await loadPage();}
async function navigate(page){if(!allowed(page))return;const sidebarScrollTop=$('.nav-scroll')?.scrollTop||0;state.page=page;state.tab='';renderShell();$('.nav-scroll').scrollTop=sidebarScrollTop;await loadPage();window.scrollTo(0,0);}
let pageTicket=0;
async function loadPage(){const ticket=++pageTicket;const content=$('#content');if(!content)return;content.innerHTML=loading();try{if(state.page==='dashboard'){const data=await api('/dashboard');if(ticket!==pageTicket)return;state.dashboard=data;renderDashboard(data);}else if(state.page==='assistant'){renderAssistant();}else if(state.page==='settings'){renderSettings();}else if(state.page==='cases'){state.data=await api('/cases');if(ticket!==pageTicket)return;renderCases();}else {state.data=await api('/resources/'+state.page);if(ticket!==pageTicket)return;await renderResource();}}catch(error){if(ticket===pageTicket&&$('#content'))$('#content').innerHTML=`<div class="error-box"><h3>${t('Something went wrong')}</h3><p>${esc(error.message)}</p>${button('Retry','retry')}</div>`;}}
function bannerArt(){return `<div class="banner-art" aria-hidden="true"><svg viewBox="0 0 240 190"><path d="M25 177h205M140 170V42M140 100c-41 1-53-23-52-44 34-4 50 15 52 44M140 72c35 0 45-22 42-44-30 1-41 17-42 44M140 130c39 1 54-20 53-44-35-1-52 17-53 44"/><path class="fill" d="M118 135h46l-7 42h-32z"/><path class="fill" d="M30 104h65v73H30z"/><path d="M37 114h51M37 123h32M38 153l12-14 13 6 19-20"/><path class="dark" d="M176 151h33v26h-33z"/><path d="M192 151v-31M192 139c-15-2-21-12-18-21 14 1 18 9 18 21M192 129c13-2 19-10 17-20-14 1-18 8-17 20M54 104V78M48 78h13M54 82l-9 8M54 82l9 8M202 43l2-6 6-2-6-2-2-6-2 6-6 2 6 2z"/></svg></div>`;}
function stat(label,value,foot,ic){return `<div class="stat-card"><div class="stat-label">${t(label)}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-number">${esc(value)}</div><div class="stat-foot"><span class="green">↗</span>${esc(t(foot))}</div></div>`;}
function chart(data){const max=Math.max(1,...data.map(x=>x.present));return `<svg class="chart" role="img" aria-label="Attendance trend" viewBox="0 0 560 190">${[0,1,2,3].map(n=>`<path class="gridline" d="M35 ${20+n*43}H550"/><text x="6" y="${24+n*43}">${Math.round(max*(1-n/3))}</text>`).join('')}${data.map((d,i)=>{const x=55+i*70;return `<rect class="${i===data.length-1?'bar-dark':'bar'}" x="${x}" y="${150-d.present/max*130}" width="24" height="${d.present/max*130}" rx="4"/><rect class="bar-late" x="${x+28}" y="${150-d.late/max*130}" width="10" height="${d.late/max*130}" rx="3"/><text x="${x+4}" y="178">${esc(day(d.day,{weekday:'short'}))}</text>`;}).join('')}</svg>`;}
function renderDashboard(d){const personal=['employee','leader'].includes(state.boot.user.role);const name=state.boot.user.name.split(' ')[0];const events=d.announcements.filter(a=>a.event_date&&a.event_date>=todayISO());$('#content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">${day(todayISO(),{weekday:'long',day:'numeric',month:'long',year:'numeric'}).toUpperCase()}</div><h1>${t('Good morning')}, ${esc(name)} <span aria-hidden="true">☀</span></h1><p class="subtitle">${t(personal?'Your workday, at a glance.':'Here’s what’s happening with your people today.')}</p></div><div class="actions">${button('Export report','export-dashboard',``, '')}<span class="button">${icon('calendar')}${day(todayISO(),{day:'numeric',month:'short'})}</span></div></div><section class="welcome-banner"><div class="welcome-copy"><div class="eyebrow">${t('People first. Always.').toUpperCase()}</div><h2>${t('Your next great workday starts here.')}</h2><p>${t('Keep your team connected, celebrate progress, and make room for what matters.')}</p>${button('View company updates','navigate','data-page="announcements"','primary small')}</div>${bannerArt()}</section><div class="stats-grid">${stat(personal?'Leave balance':'Total employees',personal?d.leave_balance:d.total_employees,personal?'days available':'Active workforce','users')}${stat('Present today',d.present,'Recorded check-ins','clock')}${stat('Pending requests',d.pending,'Awaiting human review','file')}${stat('Performance score',d.performance+'%','Weighted KPI achievement','chart')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><div><h2>${t('Attendance overview')}</h2><p>${t('The last seven calendar days')}</p></div>${button('Today','navigate','data-page="leave_requests"','small')}</div><div class="legend"><span><i class="dot light"></i>${t('Present')}</span><span><i class="dot orange"></i>${t('Late')}</span></div><div class="chart-area">${chart(d.attendance_trend)}</div></section><section class="panel"><div class="panel-head"><div><h2>${t('Quick actions')}</h2><p>${t('Your workday, at a glance.')}</p></div>${icon('spark')}</div><div class="quick-grid"><button class="quick-action" data-action="attendance" data-kind="${d.today?.check_in?'out':'in'}">${icon('clock')}${t(d.today?.check_in?'Check out':'Check in')}</button><button class="quick-action" data-action="create" data-table="leave_requests">${icon('calendar')}${t('Request time off')}</button><button class="quick-action" data-action="navigate" data-page="assistant">${icon('spark')}${t('Ask Northstar')}</button></div><div class="notice-list"><div class="notice"><div class="notice-icon">${icon('book')}</div><div><h3>${t('Learning progress')}</h3><p>${d.learning_progress}% ${t('Complete')}</p></div></div><div class="notice"><div class="notice-icon">${icon('check')}</div><div><h3>${t('Your priorities')}</h3><p>${d.tasks_done} / ${d.tasks_total} ${t('Done')} · ${d.overdue} ${t('Outstanding')}</p></div></div></div></section></div><div class="grid-main"><section class="panel"><div class="panel-head"><h2>${t('Company updates')}</h2><button class="text-link" data-action="navigate" data-page="announcements">${t('View all')} ↗</button></div><div class="notice-list">${d.announcements.length?d.announcements.slice(0,3).map(a=>`<article class="notice"><div class="notice-icon">${icon(a.kind==='Event'?'calendar':a.kind==='Policy'?'file':'message')}</div><div><h3>${esc(a.title)}</h3><p>${esc(a.content.slice(0,130))}${a.content.length>130?'…':''}</p><div class="notice-meta">${badge(a.kind)}<span>${day(a.created_at)}</span><button class="text-link" data-action="read" data-table="announcements" data-id="${a.id}">${t('View')}</button></div></div></article>`).join(''):empty()}</div></section><section class="panel"><div class="panel-head"><div><h2>${t('Department capacity')}</h2><p>${t('Open estimated effort / weekly capacity')}</p></div>${icon('chart')}</div>${d.departments.map(dep=>`<div class="department-row"><div class="row between"><span>${esc(dep.name)}</span><small>${dep.utilization}%</small></div><progress class="progress" max="100" value="${dep.utilization}"></progress><div class="inline-note">${dep.hours}h / ${dep.capacity}h · ${dep.employees} ${t('People')}</div></div>`).join('')}<div class="panel-pad">${button('Headcount analysis','ai-prompt','data-agent="retention"','small soft')}</div></section></div><div class="grid-main"><section class="panel"><div class="panel-head"><h2>${t('Your priorities')}</h2><button class="text-link" data-action="navigate" data-page="tasks">${t('View all')} ↗</button></div><div class="table-wrap"><table><thead><tr><th>${t('Title')}</th><th>${t('Employee name')}</th><th>${t('Due date')}</th><th>${t('Status')}</th></tr></thead><tbody>${d.tasks.map(task=>`<tr><td><strong>${esc(task.title)}</strong></td><td>${esc(person(task.employee_id))}</td><td>${day(task.due,{day:'numeric',month:'short'})}</td><td>${badge(task.status)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">${d.tasks_done} / ${d.tasks_total} ${t('Done')}</div></section><section class="panel"><div class="panel-head"><h2>${t('Upcoming events')}</h2>${icon('calendar')}</div><div class="notice-list">${events.length?events.map(a=>`<div class="notice"><div class="calendar-day"><b>${day(a.event_date,{day:'numeric'})}</b><small>${day(a.event_date,{month:'short'})}</small></div><div><h3>${esc(a.title)}</h3><p>${day(a.event_date,{weekday:'long',month:'long',day:'numeric'})}</p></div></div>`).join(''):`<p class="muted small-text">${t('No events scheduled')}</p>`}</div><div class="panel-head"><h2>${t('A moment of appreciation')}</h2>${icon('star')}</div><div class="notice-list">${d.recognition.slice(0,1).map(r=>`<div class="notice">${avatar(person(r.employee_id))}<div><h3>${esc(person(r.employee_id))}</h3><p>${esc(r.title)}</p><div class="notice-meta">${badge(r.badge)}</div></div></div>`).join('')}</div></section></div>${footer()}`;}

const PAGE_SUB={employees:'The people who make it all happen.',announcements:'Stay connected to what’s happening across the company.',leave_requests:'A little clarity for every working day.',payroll:'Transparent calculations. Thoughtful human review.',kpis:'Meaningful objectives, measurable progress.',reports:'Make progress visible. Make feedback useful.',learning_plans:'Small steps toward your next big thing.',jobs:'Find the people who will shape what’s next.',contracts:'One place for the details that matter.',checklists:'A warm welcome, with every detail covered.',resignations:'Thoughtful transitions, lasting relationships.',surveys:'Every voice makes a difference.',tasks:'Clear priorities. A little more room to focus.',recognition:'Great work deserves to be seen.',articles:'The answers you need, all in one place.'};
Object.assign(ar,{'The people who make it all happen.':'الأشخاص الذين يصنعون النجاح.','Stay connected to what’s happening across the company.':'ابقَ على تواصل مع مستجدات الشركة.','A little clarity for every working day.':'وضوح أكثر لكل يوم عمل.','Transparent calculations. Thoughtful human review.':'حسابات واضحة ومراجعة بشرية واعية.','Meaningful objectives, measurable progress.':'أهداف هادفة وتقدم قابل للقياس.','Make progress visible. Make feedback useful.':'تقدم واضح وملاحظات مفيدة.','Small steps toward your next big thing.':'خطوات صغيرة نحو إنجازك القادم.','Find the people who will shape what’s next.':'اكتشف المواهب التي تصنع المستقبل.','One place for the details that matter.':'مكان واحد للتفاصيل المهمة.','A warm welcome, with every detail covered.':'ترحيب دافئ مع الاهتمام بكل التفاصيل.','Thoughtful transitions, lasting relationships.':'انتقالات مدروسة وعلاقات دائمة.','Every voice makes a difference.':'كل صوت يصنع فرقاً.','Clear priorities. A little more room to focus.':'أولويات واضحة ومساحة أكبر للتركيز.','Great work deserves to be seen.':'العمل المميز يستحق التقدير.','The answers you need, all in one place.':'الإجابات التي تحتاجها في مكان واحد.'});
function canCreate(table){const s=state.boot.catalog[table];return s&&(s.manage?.includes(state.boot.user.role)||s.create_self);}
function tabs(items,current){return `<div class="tabs">${items.map(([key,label])=>`<button class="tab ${key===current?'active':''}" data-action="tab" data-tab="${key}">${t(label)}</button>`).join('')}</div>`;}
async function renderResource(){const page=state.page;let acts='';if(canCreate(page))acts+=button(page==='employees'?'Add employee':page==='recognition'?'Recognize a colleague':'Add new','create',`data-table="${page}"`,'primary');if(page==='leave_requests')acts=button('Check in','attendance','data-kind="in"')+button('Check out','attendance','data-kind="out"')+button('Request time off','create','data-table="leave_requests"','primary');if(page==='payroll'&&state.boot.user.role==='hr')acts=button('Add adjustment','create','data-table="salary_components"')+button('Simulate salary','simulate')+button('Process payroll','process-payroll','','primary');if(page==='kpis'&&['hr','manager','leader'].includes(state.boot.user.role))acts+=button('Add evaluation period','period');if(page==='jobs')acts+=button('Generate job description','job-description')+button('Headcount analysis','ai-prompt','data-agent="recruitment"');if(page==='contracts')acts+=button('Upload document','upload');if(page==='resignations'&&state.boot.user.role!=='employee')acts+=button('Workforce insights','ai-prompt','data-agent="retention"');
let subnav='';if(page==='leave_requests')subnav=tabs([['leave_requests','Leave requests'],['attendance','Attendance history']],state.tab||page);if(page==='learning_plans')subnav=tabs([['learning_plans','Learning plans'],['courses','Course library']],state.tab||page);if(page==='jobs')subnav=tabs([['jobs','Vacancies'],['candidates','Candidates'],['interviews','Interviews'],['comparison','Candidate comparison']],state.tab||page);if(page==='contracts')subnav=tabs([['contracts','Contracts'],['documents','Documents']],state.tab||page);if(page==='resignations')subnav=tabs([['resignations','Resignations'],['offboarding','Offboarding checklist']],state.tab||page);
$('#content').innerHTML=heading(PAGE_SUB[page]||'',acts)+subnav+`<div class="filters"><div class="search-box filter-input">${icon('search')}<input id="record-search" placeholder="${t('Search records…')}" aria-label="${t('Search records…')}"></div><div class="actions" id="sub-actions"></div></div><div id="records">${loading()}</div>`+footer();$('#record-search').oninput=e=>filterRecords(e.target.value);await renderTab();}
async function renderTab(){let table=state.tab||state.page;let data=state.data;$('#sub-actions').innerHTML='';if(table!==state.page&&table!=='comparison'&&table!=='offboarding'){data=table==='attendance'||table==='documents'?await api('/'+table):await api('/resources/'+table);}if(table==='offboarding')data=(await api('/resources/checklists')).filter(r=>r.kind==='Offboarding');if(table==='comparison')data=await api('/resources/candidates');if(table!==state.page&&canCreate(table))$('#sub-actions').innerHTML=button('Add new','create',`data-table="${table}"`,'small primary');if(table==='candidates'&&state.boot.user.role==='hr')$('#sub-actions').innerHTML+=button('Upload CV','upload','data-candidate="1"','small');if(table==='documents')$('#sub-actions').innerHTML=button('Upload document','upload','','small primary');state.viewTable=table;state.viewData=data;renderRecords(data,table);}
function filterRecords(query){const q=String(query||'').toLowerCase();const data=(state.viewData||[]).filter(r=>JSON.stringify(r).toLowerCase().includes(q)||person(r.employee_id||r.id).toLowerCase().includes(q));renderRecords(data,state.viewTable);}
const COLS={
 employees:[['name','Name'],['department_id','Department'],['position_id','Job title'],['work_mode','Work arrangement'],['status','Status']],
 leave_requests:[['employee_id','Employee name'],['type_id','Request type'],['start','Start date'],['end','End date'],['units','Days / hours requested'],['status','Status']],
 attendance:[['employee_id','Employee name'],['day','Date'],['check_in','Check-in'],['check_out','Check-out'],['minutes','Hours'],['late_minutes','Late minutes'],['overtime_minutes','Overtime'],['exception','Exception']],
 payroll:[['employee_id','Employee name'],['month','Month'],['gross_cents','Gross salary'],['deductions_cents','Deductions'],['net_cents','Net salary'],['status','Status']],
 salary_components:[['employee_id','Employee name'],['name','Name'],['kind','Type'],['amount_cents','Amount (minor units)'],['reason','Reason']],
 kpis:[['employee_id','Employee name'],['title','Title'],['target','Target'],['actual','Actual'],['weight','Weight'],['achievement','Achievement'],['status','Status']],
 reports:[['employee_id','Employee name'],['month','Month'],['kind','Type'],['accomplishments','Title'],['workload','Workload (1–5)'],['status','Status']],
 learning_plans:[['employee_id','Employee name'],['course_id','Course'],['due','Due date'],['progress','Progress'],['pre_score','Before'],['post_score','After']],
 candidates:[['name','Name'],['job_id','Vacancy'],['skills','Job-related skills'],['stage','Status']],
 interviews:[['candidate_id','Candidate'],['interviewer_id','Interviewer'],['scheduled_at','Interview time'],['stage','Interview stage'],['status','Status']],
 contracts:[['employee_id','Employee name'],['title','Title'],['end','Expiry date'],['probation_end','Probation ends'],['notice_days','Contractual notice days'],['status','Status']],
 documents:[['name','Name'],['employee_id','Employee name'],['category','Category'],['created_at','Date']],
 resignations:[['employee_id','Employee name'],['reason','Reason'],['submitted','Date'],['last_day','Proposed last working day'],['status','Status']],
 tasks:[['title','Title'],['employee_id','Employee name'],['due','Due date'],['priority','Priority'],['estimated_hours','Estimated hours'],['actual_hours','Actual hours'],['status','Status']],
 comparison:[['id','Candidate'],['coverage','Match'],['matched','Job-related skills'],['missing','Missing skills'],['stage','Status']]
};
function cell(r,key,table){let value=r[key];if(key==='achievement')return `<progress class="progress" value="${Math.min(100,r.direction==='lower'?100*r.target/Math.max(r.actual,.001):100*r.actual/r.target)}" max="100"></progress><small>${Math.round(Math.min(100,r.direction==='lower'?100*r.target/Math.max(r.actual,.001):100*r.actual/r.target))}%</small>`;if(key.endsWith('_cents'))return `<span class="money">${currency(value)}</span>`;if(['status','stage','priority','work_mode'].includes(key))return badge(value||'');if(key==='employee_id'||key==='interviewer_id')return `<div class="person-cell">${avatar(person(value),Number(value))}<strong>${esc(person(value))}</strong></div>`;if(table==='employees'&&key==='name')return `<div class="person-cell">${avatar(value,r.id)}<div><strong>${esc(value)}</strong><small>${esc(r.code)}</small></div></div>`;const keys={department_id:'departments',position_id:'positions',type_id:'leave_types',course_id:'courses'};if(keys[key])return esc(lookup(keys[key],value));if(key==='job_id')return esc((state.jobs||[]).find(j=>j.id===value)?.title||'#'+value);if(key==='candidate_id')return esc((state.candidates||[]).find(j=>j.id===value)?.name||'#'+value);if(key==='skills')return parse(value).map(s=>badge(s)).join(' ');if(['start','end','day','due','probation_end','last_day','submitted','created_at'].includes(key))return day(value);if(key==='scheduled_at')return day(value,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});if(key==='check_in'||key==='check_out')return value?day(value,{hour:'2-digit',minute:'2-digit'}):'—';if(key==='minutes')return (value/60).toFixed(1);if(key==='progress')return `<progress class="progress" value="${value}" max="100"></progress><small>${value}%</small>`;return esc(String(value??'—').slice(0,110));}
function rowActions(r,table){let html=button(table==='documents'?'Download':'View',table==='documents'?'download':'view',`data-table="${table}" data-id="${r.id}"`,'small');const role=state.boot.user.role;const spec=state.boot.catalog[table];if(spec?.manage?.includes(role)&&table!=='payroll')html+=button('Edit','edit',`data-table="${table}" data-id="${r.id}"`,'small');if(table==='leave_requests'&&r.status==='Pending'&&r.employee_id!==state.boot.user.employee_id&&(role==='hr'||r.approver_id===state.boot.user.employee_id))html+=button('Approve','leave-decision',`data-id="${r.id}" data-decision="Approved"`,'small soft')+button('Reject','leave-decision',`data-id="${r.id}" data-decision="Rejected"`,'small danger');if(table==='payroll'&&role==='hr'&&r.status==='Draft')html+=button('Approve','approve-payroll',`data-id="${r.id}"`,'small soft');if(table==='tasks')html+=button('Manage task','task',`data-id="${r.id}"`,'small');if(table==='learning_plans')html+=button('Update progress','learning-progress',`data-id="${r.id}"`,'small');if(table==='kpis')html+=button(!spec.manage?.includes(role)?'Request review':'Approve','kpi-action',`data-id="${r.id}"`,'small');if(table==='reports'&&role!=='owner')html+=button(role==='employee'?'Request review':'Reviewer feedback','report-feedback',`data-id="${r.id}"`,'small');if(table==='candidates'&&role==='hr')html+=button('Move stage','candidate-stage',`data-id="${r.id}"`,'small');if(table==='interviews')html+=button('Feedback','interview-feedback',`data-id="${r.id}"`,'small');if(table==='resignations'&&role==='hr'&&r.status!=='Completed')html+=button(r.status==='Submitted'?'Acknowledge':'Complete offboarding','offboarding',`data-id="${r.id}" data-status="${r.status}"`,'small');return `<div class="actions">${html}</div>`;}
function renderRecords(data,table){const root=$('#records');if(!root)return;if(!data.length){root.innerHTML=empty(state.viewData?.length?'No matching records':'No records yet');return;}if(['announcements','articles','jobs','recognition','courses','surveys'].includes(table)){root.innerHTML=`<div class="cards-grid">${data.map(r=>card(r,table)).join('')}</div>`;return;}if(table==='checklists'||table==='offboarding'){const group=new Map();for(const r of data.filter(r=>table==='offboarding'?r.kind==='Offboarding':r.kind==='Onboarding')){const arr=group.get(r.employee_id)||[];arr.push(r);group.set(r.employee_id,arr);}root.innerHTML=group.size?[...group.entries()].map(([eid,items])=>`<section class="panel"><div class="panel-head"><div class="person-cell">${avatar(person(eid))}<div><h2>${esc(person(eid))}</h2><p>${items.filter(r=>r.done).length} / ${items.length} ${t('Complete')}</p></div></div><progress class="progress" value="${items.filter(r=>r.done).length}" max="${items.length}"></progress></div>${items.map(r=>`<label class="check-row"><input type="checkbox" data-check-id="${r.id}" ${r.done?'checked':''}><span class="${r.done?'done':''}">${esc(r.title)}</span><small class="muted">${day(r.due,{day:'numeric',month:'short'})}</small></label>`).join('')}</section>`).join(''):empty();return;}const cols=COLS[table]||[['title','Title'],['status','Status']];root.innerHTML=`<div class="panel"><div class="table-wrap"><table><thead><tr>${cols.map(([,label])=>`<th>${t(label)}</th>`).join('')}<th>${t('Actions')}</th></tr></thead><tbody>${data.map(r=>`<tr>${cols.map(([key])=>`<td>${cell(r,key,table)}</td>`).join('')}<td>${rowActions(r,table)}</td></tr>`).join('')}</tbody></table></div><div class="table-footer">${data.length} ${t('records')} · ${t('All changes are saved to your local database.')}</div></div>`;if(table==='comparison')renderComparison(data);}
function card(r,table){let title=r.title;let body=r.content||r.description||r.detail||r.objective||'';let top=badge(r.status||r.badge||r.kind||r.skill||'');let bottom='';if(table==='recognition'){title=person(r.employee_id);top=`<div class="recognition-badge">${icon('star')}</div>`+badge(r.badge);body=r.title+'\n\n'+r.detail;}if(table==='surveys'){body=parse(r.questions).map(t).join(' · ');bottom=button('Respond','survey',`data-id="${r.id}"`,'small primary');if(['hr','owner','manager'].includes(state.boot.user.role))bottom+=button('View results','survey-results',`data-id="${r.id}"`,'small');}else if(table==='courses'){body=t('Skill')+': '+r.skill+' · '+r.duration_hours+'h · '+currency(r.cost_cents);bottom=`<a class="button small" href="${esc(r.resource)}" target="_blank" rel="noopener noreferrer">${t('View')} ↗</a>`;}else bottom=button(table==='articles'?'Read article':'View','view',`data-table="${table}" data-id="${r.id}"`,'small');if(state.boot.catalog[table]?.manage?.includes(state.boot.user.role))bottom+=button('Edit','edit',`data-table="${table}" data-id="${r.id}"`,'small');return `<article class="panel record-card article-card"><div>${top}</div><h3>${esc(title)}</h3><p>${esc(body.slice(0,210))}${body.length>210?'…':''}</p><div class="card-bottom"><span class="helper">${r.event_date?day(r.event_date):r.category?esc(r.category):r.created_at?day(r.created_at):''}</span><div class="actions">${bottom}</div></div></article>`;}
async function renderComparison(data){state.jobs=await api('/resources/jobs');const cards=data.map(c=>{const j=state.jobs.find(j=>j.id===c.job_id);const required=parse(j?.skills||'[]');const skills=parse(c.skills).map(s=>s.toLowerCase());const matched=required.filter(s=>skills.includes(s.toLowerCase()));return {...c,coverage:required.length?Math.round(100*matched.length/required.length)+'%':'—',matched:matched.join(', '),missing:required.filter(s=>!matched.includes(s)).join(', ')||'—'};});const cols=COLS.comparison;$('#records').innerHTML=`<div class="info-strip">${state.lang==='ar'?'تغطية المهارات المسجلة فقط وليست درجة توظيف. لا تُستخدم السمات الشخصية المحمية. يتخذ الإنسان جميع قرارات التوظيف.':'Recorded skill coverage only, not a hiring score. Protected personal attributes are excluded. A human makes all hiring decisions.'}</div><div class="panel table-wrap"><table><thead><tr>${cols.map(([,l])=>`<th>${t(l)}</th>`).join('')}</tr></thead><tbody>${cards.map(r=>`<tr>${cols.map(([k])=>`<td>${k==='id'?esc(r.name):esc(t(r[k]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
let previousFocus=null;
function modal(title,body,actions='',wide=false){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(t(title))}"><header class="modal-header"><h2>${esc(t(title))}</h2><button class="icon-button" data-action="close-modal" aria-label="${t('Close')}">${icon('close')}</button></header><div class="modal-body">${body}</div><footer class="modal-actions">${actions||button('Close','close-modal')}</footer></section></div>`;document.body.classList.add('modal-open');setTimeout(()=>{$('input,select,textarea,button',$('.modal'))?.focus();},20);}
function closeModal(){$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');previousFocus?.focus();}
function optionsFor(field){const look=state.boot.lookups;const map={department:'departments',position:'positions',team:'teams',employee:'scoped_employees',leave_type:'leave_types',course:'courses',period:'periods',handler:'case_handlers'};if(map[field.type])return look[map[field.type]].map(r=>[r.id,r.name||r.title]);if(field.type==='job')return (state.jobs||[]).map(r=>[r.id,r.title]);if(field.type==='candidate')return (state.candidates||[]).map(r=>[r.id,r.name]);return (field.options||[]).map(v=>[v,t(v)]);}
function fieldHTML(field,value=''){const {name,label,type,required}=field;let input='';const attrs=`name="${name}" id="field-${name}" ${required?'required':''}`;if(type==='checkbox')input=`<input ${attrs} type="checkbox" ${value?'checked':''}>`;else if(type==='textarea')input=`<textarea class="field-input" ${attrs} maxlength="15000">${esc(value)}</textarea>`;else if(field.options||['department','position','team','employee','leave_type','course','period','job','candidate','handler'].includes(type)){const opts=optionsFor(field);input=`<select class="field-input" ${attrs}>${!required?`<option value="">—</option>`:''}${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select>`;}else{const val=type==='list'&&typeof value==='string'&&value.startsWith('[')?parse(value).join(', '):value;input=`<input class="field-input" ${attrs} type="${type==='list'?'text':type}" value="${esc(val)}" ${type==='number'?'step="any" min="0"':''} ${type==='password'?'minlength="10"':''} maxlength="15000">`;}return `<div class="field ${['textarea','list'].includes(type)?'full':''}"><label for="field-${name}">${esc(t(label))}${required?' *':''}</label>${input}</div>`;}
function simpleField(name,label,type='text',options=null,required=true){return {name,label,type,options,required};}
function formModal(title,fields,values,onSubmit,submitLabel='Save',extra=''){const body=`${extra}<form id="modal-form"><div class="form-grid">${fields.map(f=>fieldHTML(f,values[f.name]??(f.type==='date'?todayISO():f.type==='month'?todayISO().slice(0,7):f.type==='number'?0:''))).join('')}</div><div id="form-error" role="alert"></div></form>`;modal(title,body,button('Cancel','close-modal')+`<button class="button primary" type="submit" form="modal-form">${t(submitLabel)}</button>`);$('#modal-form').onsubmit=async e=>{e.preventDefault();const b=$('button[form="modal-form"]');b.disabled=true;const p=Object.fromEntries(new FormData(e.target));for(const f of fields){if(f.type==='checkbox')p[f.name]=$(`[name="${f.name}"]`,e.target).checked;if(f.type==='number')p[f.name]=Number(p[f.name]);}try{const result=await onSubmit(p);if(result?.keepOpen)return;closeModal();toast(result?.message||t('Save changes'));if(state.boot){await refreshBootstrap();await loadPage();}}catch(error){if($('#form-error'))$('#form-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`;else toast(error.message,true);}finally{if(b.isConnected)b.disabled=false;}};}
async function refreshBootstrap(){state.boot=await api('/bootstrap');}
async function resourceRecord(table,id){return (state.viewTable===table?state.viewData:table===state.page?state.data:null)?.find(r=>r.id===Number(id))||(await api('/resources/'+table)).find(r=>r.id===Number(id));}
async function recordForm(table,id){const spec=state.boot.catalog[table];if(!spec)return;let r=id?await resourceRecord(table,id):{};if(['jobs','candidates','interviews'].includes(table)){state.jobs=await api('/resources/jobs');state.candidates=await api('/resources/candidates');}let fields=spec.fields.map(f=>({...f}));if(spec.create_self&&(!spec.manage?.includes(state.boot.user.role)))fields=fields.filter(f=>f.name!=='employee_id');if(table==='recognition'){fields=fields.map(f=>f.name==='employee_id'?{...f,type:'select',options:null}:f);const dir=state.boot.lookups.employees;const field=fields.find(f=>f.name==='employee_id');field.type='employee';state.boot.lookups.scoped_employees=dir;}
if(table==='reports'&&state.boot.user.role!=='employee'&&!id)fields.unshift(simpleField('employee_id','Employee name','employee'));
if(table==='employees'&&!id)r={salary_cents:2500000,annual_days:21,skills:'Communication',employment_type:'Full time',work_mode:'Office',...r};if(table==='kpis'&&!id)r={weight:25,target:100,actual:0,...r};if(table==='tasks'&&!id)r={complexity:3,estimated_hours:4,...r};if(table==='reports'&&!id)r={workload:3,clarity:3,...r};
formModal((id?'Edit':'Add new')+' · '+t(spec.label),fields,r,p=>api('/resources/'+table+(id?'/'+id:''),id?'PATCH':'POST',p),id?'Save changes':'Create record');}
function recordDetails(r,table){const fields=state.boot.catalog[table]?.fields||[];return `<dl class="detail-grid">${Object.entries(r).filter(([k])=>!['storage_key','secret_hash','cv_text'].includes(k)).map(([key,value])=>{const label=fields.find(f=>f.name===key)?.label||({employee_id:'Employee name',created_at:'Date',net_cents:'Net salary',gross_cents:'Gross salary',basic_cents:'Basic salary',additions_cents:'Additions',deductions_cents:'Deductions',status:'Status',stage:'Status',feedback:'Feedback',breakdown:'Details',id:'ID'})[key]||key.replaceAll('_',' ');let val=typeof value==='string'&&value.startsWith('[')?parse(value).join(', '):value;let rendered=key.endsWith('_cents')?currency(value):key==='employee_id'?person(value):val;if(key==='breakdown')rendered=JSON.stringify(parse(value),null,2);return `<div class="detail-item"><dt>${esc(t(label))}</dt><dd>${esc(rendered??'—')}</dd></div>`;}).join('')}</dl>`;}
async function viewRecord(table,id){const r=await resourceRecord(table,id);if(!r)return;if(['announcements','articles','jobs','recognition','courses'].includes(table)){modal(r.title,`<div class="row between">${badge(r.status||r.kind||r.badge||r.skill||'')}${r.created_at?`<span class="helper">${day(r.created_at)}</span>`:''}</div><p class="detail-content">${esc(r.content||r.description||r.detail||r.objective||'')}</p>${table==='jobs'?`<p>${t('Required skills')}: ${parse(r.skills).map(s=>badge(s)).join(' ')}</p>`:''}`);return;}let body=recordDetails(r,table),actions='';if(table==='employees'){const history=await api('/history/'+r.id);body=`<div class="employee-header">${avatar(r.name)}<div><h2>${esc(r.name)}</h2><span class="muted">${esc(lookup('positions',r.position_id))}</span></div></div>`+body+`<h3>${t('Employee history')}</h3><div class="timeline">${history.length?history.map(h=>`<p>${esc(h.kind)}<small>${day(h.created_at)}</small>${esc(h.detail)}</p>`).join(''):`<p>${t('No records yet')}</p>`}</div>`;if(state.boot.user.role==='hr')actions=button('Create user account','provision',`data-id="${r.id}"`);}if(table==='payroll'){const b=parse(r.breakdown);body=`<div class="eyebrow">NORTHSTAR PEOPLE · ${t('Payroll')}</div><h2>${esc(person(r.employee_id))}</h2><p class="muted">${r.month} · ${t(r.status)}</p><dl class="detail-grid">${[['Basic salary',r.basic_cents],['Additions',r.additions_cents],['Gross salary',r.gross_cents],['Deductions',r.deductions_cents],['Net salary',r.net_cents]].map(([l,v])=>`<div class="detail-item"><dt>${t(l)}</dt><dd>${currency(v)}</dd></div>`).join('')}</dl><h3>${t('Details')}</h3><div class="detail-content">${(b.components||[]).map(c=>`${esc(c.name)} (${esc(c.kind)}): ${currency(c.amount_cents)} — ${esc(c.reason)}`).join('<br>')}<br>${t('Overtime')}: ${currency(b.overtime_cents)}<br>${t('Late minutes')}: ${currency(b.late_cents)}<br>${t('Leave requests')}: ${currency(b.unpaid_leave_cents)}</div><p class="helper">${state.lang==='ar'?'نسخة تجريبية: لا تشمل الضرائب والتأمينات القانونية.':'Demonstration calculation; statutory taxes and insurance are not included.'}</p>`;actions=button('Print payslip','print');}modal(table==='payroll'?'Payroll':r.title||r.name||t(state.boot.catalog[table]?.label||'Details'),body,actions+button('Close','close-modal'),true);}
function renderCases(){const handler=state.boot.user.role==='hr';$('#content').innerHTML=heading('A confidential space to speak up.',button('Track a case','track-case')+button('Submit a case','submit-case','','primary'))+`<div class="info-strip">${state.lang==='ar'?'البلاغ ادعاء وليس دليلاً. يُحظر الانتقام. تقتصر التفاصيل الحساسة على مسؤولي الحالات المخولين. البلاغات المجهولة لا تخزن رقم الموظف؛ احتفظ بالرمز للمتابعة وتجنب التفاصيل التي تكشف هويتك.':'A complaint is an allegation, not proof. Retaliation is prohibited. Sensitive details are restricted to authorized case handlers. Anonymous cases store no employee ID; keep your token for follow-up and avoid identifying details in your narrative.'}</div><div class="panel"><div class="table-wrap"><table><thead><tr><th>${t('Case reference')}</th><th>${t('Title')}</th><th>${t('Type')}</th><th>${t('Status')}</th><th>${t('Due date')}</th><th>${t('Actions')}</th></tr></thead><tbody>${state.data.map(r=>`<tr><td>${esc(r.case_ref)}</td><td>${esc(r.title)}</td><td>${t(r.anonymous?'Anonymous':'Identified')}</td><td>${badge(r.status)}</td><td>${day(r.due)}</td><td>${handler?button('View','case-detail',`data-id="${r.id}"`,'small'):esc(r.resolution||'—')}</td></tr>`).join('')}</tbody></table></div>${!state.data.length?empty():''}</div>`+footer();}
function submitCase(){formModal('Submit a case',[simpleField('title','Title'),simpleField('kind','Type','select',['Complaint','Suggestion']),simpleField('anonymous','Anonymous','checkbox',null,false),simpleField('detail','Details','textarea')],{anonymous:true},async p=>{const result=await api('/cases','POST',p);modal('Case reference',`<p class="small-text">${esc(result.message)}</p><div class="case-secret">${t('Case reference')}: ${esc(result.case_ref)}<br>${t('Follow-up token')}: ${esc(result.token)}</div><p class="danger-note">${state.lang==='ar'?'احفظ هذا الرمز الآن. لا يمكن استعادته.':'Save this token now. It cannot be recovered later.'}</p>`,button('Download','download-case',`data-ref="${result.case_ref}" data-token="${result.token}"`)+button('Close','close-modal'));return {keepOpen:true};},'Submit');}
function trackCase(){formModal('Track a case',[simpleField('case_ref','Case reference'),simpleField('token','Follow-up token')],{},async p=>{const result=await api('/cases','POST',{...p,action:'track'});showTrackedCase(result,p);return {keepOpen:true};},'View');}
function showTrackedCase(r,credentials){modal('Track a case',`<h3>${esc(r.case_ref)} · ${esc(r.title)}</h3>${badge(r.status)}<p class="detail-content">${esc(r.resolution)}</p><div class="timeline">${r.history.map(h=>`<p><small>${day(h.created_day)} · ${esc(h.author)}</small>${esc(h.message)}</p>`).join('')}</div><form id="case-followup"><div class="field"><label for="followup">${t('Follow-up message')}</label><textarea class="field-input" id="followup" name="message" required maxlength="5000"></textarea></div><div id="followup-error"></div><button class="button primary" type="submit">${t('Send')}</button></form>`);$('#case-followup').onsubmit=async e=>{e.preventDefault();try{const result=await api('/cases','POST',{...credentials,action:'followup',message:new FormData(e.target).get('message')});showTrackedCase(result,credentials);toast(t('Save changes'));}catch(error){$('#followup-error').textContent=error.message;}};}
function caseDetail(id){const r=state.data.find(r=>r.id===Number(id));formModal('Case owner',[simpleField('status','Status','select',['Open','In review','Awaiting information','Resolved','Closed']),simpleField('resolution','Resolution','textarea',null,false),simpleField('message','Follow-up message','textarea',null,false)],r,p=>api('/cases','POST',{...p,id:r.id,action:'update'}),'Save',`<h3>${esc(r.title)} · ${esc(r.case_ref)}</h3><p class="detail-content">${esc(r.detail)}</p><p class="helper">${t(r.anonymous?'Anonymous':'Identified')} · ${t('Case owner')}: HR</p>`);}
async function showSurvey(id){const r=await resourceRecord('surveys',id);const qs=parse(r.questions);modal(r.title,`<div class="info-strip">${state.lang==='ar'?(r.anonymous?'الإجابات مجهولة الهوية. يرى المسؤولون النتائج المجمعة بعد حد الخصوصية. لا يُخزن رقم الموظف مع إجابتك.':'استبيان معلوم الهوية. تُحفظ هويتك مع الإجابة؛ تعرض الواجهة نتائج مجمعة للمسؤولين المصرح لهم.'):(r.anonymous?'Anonymous survey. Managers, HR and the owner see aggregate results only after the privacy threshold. Your employee ID is not stored with the response.':'Identified survey: your employee ID is stored with your response. Authorized managers, HR and the owner use aggregate results in this interface.')}</div><form id="survey-form">${qs.map((q,i)=>`<div class="survey-question"><span>${esc(t(q))}</span><div class="rating">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="q${i}" value="${n}" required>${n}</label>`).join('')}</div></div>`).join('')}<div class="field"><label for="survey-comment">${t('Comments (optional)')}</label><textarea class="field-input" name="comment" id="survey-comment" maxlength="3000"></textarea></div><div id="survey-error" role="alert"></div></form>`,button('Cancel','close-modal')+`<button class="button primary" form="survey-form" type="submit">${t('Submit')}</button>`);$('#survey-form').onsubmit=async e=>{e.preventDefault();const b=$('button[form="survey-form"]');b.disabled=true;try{const p=new FormData(e.target);await api('/surveys/'+id,'POST',{answers:qs.map((_,i)=>Number(p.get('q'+i))),comment:p.get('comment')});closeModal();toast(t('Response recorded'));}catch(error){$('#survey-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`;}finally{b.disabled=false;}};}
async function surveyResults(id){const r=await api('/surveys/'+id);modal('View results',r.suppressed?`<div class="info-strip">${esc(r.message)}</div>`:`<p class="helper">${r.count} ${t('records')} · 1–5</p>${r.questions.map((q,i)=>`<div class="department-row"><div class="row between"><span>${esc(t(q))}</span><b>${r.scores[i]}</b></div><progress class="progress" max="5" value="${r.scores[i]}"></progress></div>`).join('')}<h3>${t('Department')}</h3>${r.departments.map(d=>`<p class="small-text">${esc(d.department)}: ${d.suppressed?esc(d.message):d.scores.join(' / ')}</p>`).join('')}`);}
function renderSettings(){$('#content').innerHTML=heading('Configure company policies',button('Create user account','provision')+button('Add request type','leave-type'))+`<div class="info-strip">${t('Policy settings are applied to new calculations and requests.')}</div><section class="panel panel-pad"><form id="settings-form"><label for="settings-json" class="helper">${t('Configure company policies')} (JSON)</label><textarea class="field-input settings-area" id="settings-json" spellcheck="false">${esc(JSON.stringify(Object.fromEntries(Object.entries(state.boot.settings).filter(([k])=>k!=='ai_mode')),null,2))}</textarea><div id="settings-error" role="alert"></div><p class="helper">${state.lang==='ar'?'يستخدم workdays ترقيم Python: الاثنين 0 والأحد 6. المبالغ بالقرش. إعدادات الموقع تطبق على العاملين المكتبيين فقط ما لم تُفعّل apply_remote.':'workdays uses Python weekdays: Monday 0, Sunday 6. Money is in minor currency units. Geofencing applies to Office workers unless apply_remote is enabled.'}</p><button class="button primary" type="submit">${t('Save policies')}</button></form></section>`+footer();$('#settings-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{const p=JSON.parse($('#settings-json').value);const result=await api('/settings','PATCH',p);await refreshBootstrap();toast(result.message);}catch(error){$('#settings-error').innerHTML=`<div class="form-error">${esc(error.message)}</div>`;}finally{b.disabled=false;}};}
function agentAllowed(key){const role=state.boot.user.role;if(key==='complaints')return role==='hr';if(key==='recruitment')return ['hr','manager','leader'].includes(role);if(key==='retention')return role!=='employee';return true;}
function renderAssistant(){$('#content').innerHTML=heading('Ask about your authorized records or current company policies.')+`<div class="info-strip">${state.boot.settings.ai_mode==='live'?(state.lang==='ar'?'الذكاء الاصطناعي المباشر مُفعّل. البيانات المصرح بها تُرسل للمزود المهيأ.':'Live AI configured. Authorized evidence is sent to the configured provider.'):(state.lang==='ar'?'ذكاء تجريبي: إجابات محاكاة قائمة على القواعد. لا يتم الاتصال بنموذج ذكاء اصطناعي.':'Demo AI: simulated, rule-based answers. No AI model is called.')} ${state.lang==='ar'?'توصيات استشارية تخضع للمراجعة البشرية.':'Recommendations are advisory and require human review.'}</div><div class="ai-layout"><aside class="panel agent-list"><button class="agent-choice ${!state.agent?'active':''}" data-action="agent" data-agent="">${icon('spark')}${t('Orchestrator')}</button>${Object.entries(state.boot.agents).filter(([k])=>agentAllowed(k)).map(([k,a])=>`<button class="agent-choice ${state.agent===k?'active':''}" data-action="agent" data-agent="${k}">${icon(({recruitment:'briefcase',performance:'chart',complaints:'message',payroll:'wallet',attendance:'clock',learning:'book',retention:'heart',records:'folder'})[k])}${esc(state.lang==='ar'?({recruitment:'وكيل التوظيف',performance:'وكيل الأداء والتطوير',complaints:'وكيل الشكاوى والملاحظات',payroll:'وكيل الرواتب',attendance:'وكيل الحضور',learning:'وكيل التعلم',retention:'وكيل الاحتفاظ',records:'وكيل السجلات'})[k]:a.label)}</button>`).join('')}</aside><section class="panel chat-panel"><div class="panel-head"><h2>✳ Northstar Intelligence</h2>${badge(state.boot.settings.ai_mode==='live'?'Live AI':'Demo AI')}</div><div class="chat-messages" id="chat-messages">${state.messages.length?'':`<div class="empty">${icon('spark')}<h3>${t('Ask Northstar')}</h3><p>${t('Ask about your authorized records or current company policies.')}</p><div class="actions">${button(state.lang==='ar'?'ما هو رصيد إجازاتي؟':'What is my leave balance?','suggestion','data-message="What is my leave balance?"')}${button(state.lang==='ar'?'اقترح خطة تدريب':'Recommend training for my skill gaps','suggestion','data-message="Recommend training for my skill gaps"')}</div></div>`}</div><form class="chat-form" id="chat-form"><input class="field-input" name="message" placeholder="${t('Ask a question…')}" aria-label="${t('Ask a question…')}" required maxlength="3000"><button class="button primary" type="submit">${t('Send')} ${icon('arrow')}</button></form></section></div>`+footer();renderMessages();$('#chat-form').onsubmit=e=>{e.preventDefault();sendMessage(new FormData(e.target).get('message'));};}
function renderMessages(){const root=$('#chat-messages');if(!root||!state.messages.length)return;root.innerHTML=state.messages.map(m=>m.role==='user'?`<div class="chat-message user">${esc(m.text)}</div>`:`<div class="chat-message assistant"><span class="policy-tag">${esc(m.result.agent_label)} · ${esc(m.result.mode)}</span><p>${esc(m.result.answer)}</p><b>${t('Recommendations')}</b><ul>${m.result.recommendations.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><small>${t('Evidence')}: ${m.result.evidence.map(esc).join(' · ')}</small><small>${esc(m.result.fallback||m.result.disclosure)}</small><small>${esc(m.result.caution)}</small></div>`).join('');root.scrollTop=root.scrollHeight;}
async function sendMessage(text){if(state.loading)return;state.loading=true;state.messages.push({role:'user',text});renderMessages();const form=$('#chat-form');$('input',form).value='';$('button',form).disabled=true;const busy=document.createElement('div');busy.className='chat-message';busy.textContent=t('Thinking…');$('#chat-messages').append(busy);try{const result=await api('/ai','POST',{message:text,...(state.agent?{agent:state.agent}:{})});state.messages.push({role:'assistant',result});}catch(error){toast(error.message,true);}finally{state.loading=false;renderMessages();if($('button',form))$('button',form).disabled=false;}}
async function aiPrompt(agent,message){state.agent=agent;await navigate('assistant');if(message)await sendMessage(message);else $('input[name=message]')?.focus();}
function downloadText(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function uploadForm(candidate=false){const fields=[simpleField(candidate?'candidate_id':'employee_id',candidate?'Candidate':'Employee name',candidate?'candidate':'employee'),simpleField('category','Category','select',candidate?['CV']:['Identity','Contract','Qualification','General'])];formModal(candidate?'Upload CV':'Upload document',fields,{employee_id:state.boot.user.employee_id},async p=>{const file=$('#upload-file').files[0];if(!file)throw new Error(t('File')+' is required');if(file.size>5*1024*1024)throw new Error('Maximum file size is 5 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});return api('/documents','POST',{...p,name:file.name,data});},'Save',`<div class="field"><label for="upload-file">${t('File')} · max 5 MB</label><input id="upload-file" class="field-input" type="file" accept=".txt,.pdf,.docx,.png,.jpg,.jpeg"></div><p class="helper">${state.lang==='ar'?'تُخزن الملفات بشكل خاص. استخراج TXT وDOCX مدمج. يتطلب PDF مكتبة pypdf الاختيارية.':'Files are stored privately. TXT and DOCX text extraction is built in. PDF extraction requires optional pypdf.'}</p>`);}
async function attendance(kind){let coords={};const emp=(await api('/resources/employees')).find(e=>e.id===state.boot.user.employee_id);const g=state.boot.settings.geofence;if(g.enabled&&(emp.work_mode==='Office'||g.apply_remote)){coords=await new Promise((resolve,reject)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude}),()=>reject(new Error('Location permission is required by the attendance policy.')),{timeout:10000}):reject(new Error('Geolocation is unavailable.')));}const result=await api('/attendance','POST',{action:kind,...coords});toast(result.message);await loadPage();}
async function notifications(){const d=await api('/dashboard');modal('Notifications',d.notifications.length?d.notifications.map(n=>`<div class="notice ${!n.read?'notification-unread':''}"><div class="notice-icon">${icon('bell')}</div><div><h3>${esc(n.title)}</h3><p>${esc(n.detail)}</p><div class="notice-meta">${day(n.created_at)}</div></div></div>`).join(''):empty(),button('Mark all read','read-notifications')+button('Close','close-modal'));}
async function action(el){const act=el.dataset.action;const id=Number(el.dataset.id);const table=el.dataset.table||state.viewTable||state.page;
if(act==='navigate')return navigate(el.dataset.page);
if(act==='retry')return loadPage();
if(act==='language'){state.lang=state.lang==='en'?'ar':'en';if(state.boot){renderShell();await loadPage();}else renderLogin();return;}
if(act==='mobile-menu'){$('#sidebar').classList.toggle('open');return;}
if(act==='demo-account'){$('#email').value=el.dataset.email;$('#password').value='Demo2026!';return;}
if(act==='logout'){await api('/logout','POST',{});state.boot=null;state.messages=[];state.page='dashboard';state.agent='';renderLogin();return;}
if(act==='close-modal'){closeModal();return;}
if(act==='create')return recordForm(table);
if(act==='edit')return recordForm(table,id);
if(act==='view'||act==='read')return viewRecord(table,id);
if(act==='tab'){state.tab=el.dataset.tab;return renderResource();}
if(act==='attendance')return attendance(el.dataset.kind);
if(act==='export-dashboard'){downloadText('northstar-workforce-report.json',JSON.stringify({generated_at:new Date().toISOString(),role:state.boot.user.role,...state.dashboard},null,2),'application/json');return;}
if(act==='leave-decision'){formModal(el.dataset.decision,[simpleField('reason','Decision reason','textarea',null,false)],{},p=>api('/leave/'+id+'/decision','POST',{...p,decision:el.dataset.decision}),'Save',`<p class="small-text">${state.lang==='ar'?'سيسجل القرار في تاريخ الموافقات ويُخطر الموظف. لا يمكن تعديله بعد الحفظ.':'The decision will be recorded in approval history and the employee notified. It cannot be edited after saving.'}</p>`);return;}
if(act==='process-payroll'){formModal('Process payroll',[simpleField('month','Payroll month','month')],{},p=>api('/payroll','POST',{...p,action:'process'}),'Process payroll',`<p class="small-text">${state.lang==='ar'?'تُحسب مسودات الرواتب وفق السياسات الحالية. تُعاد حسابات المسودات الموجودة وتُحفظ الرواتب المعتمدة.':'Prepare drafts using current deterministic policies. Existing drafts are recalculated; approved payroll remains locked.'}</p>`);return;}
if(act==='approve-payroll'){formModal('Approve',[],{},()=>api('/payroll','POST',{id,action:'approve'}),'Approve',`<p>${state.lang==='ar'?'اعتماد قسيمة الراتب؟ راجع المكونات أولاً. سيُقفل الحساب ويُخطر الموظف.':'Approve this payslip? Review its itemized calculation first. Approval locks the calculation and notifies the employee.'}</p>`);return;}
if(act==='simulate'){formModal('Simulate salary',[simpleField('employee_id','Employee name','employee'),simpleField('month','Payroll month','month')],{},async p=>{const result=await api('/payroll','POST',{...p,action:'simulate'});modal('Simulate salary',recordDetails(result,'payroll'));return {keepOpen:true};},'Simulate salary');return;}
if(act==='period'){formModal('Add evaluation period',[simpleField('name','Name'),simpleField('start','Start','date'),simpleField('end','End','date')],{},p=>api('/periods','POST',p));return;}
if(act==='task'){const r=await resourceRecord('tasks',id);formModal('Manage task',[simpleField('status','Status','select',['To do','In progress','Done']),simpleField('actual_hours','Actual hours','number')],r,p=>api('/resources/tasks/'+id,'PATCH',p));return;}
if(act==='learning-progress'){const r=await resourceRecord('learning_plans',id);formModal('Update progress',[simpleField('progress','Progress','number'),simpleField('post_score','Post-assessment (0–100)','number'),simpleField('application','Practical application','textarea',null,false)],r,p=>api('/resources/learning_plans/'+id,'PATCH',p));return;}
if(act==='kpi-action'){const r=await resourceRecord('kpis',id);const employee=!state.boot.catalog.kpis.manage.includes(state.boot.user.role);formModal(employee?'Request review':'Performance',[simpleField('actual','Actual result','number'),simpleField('status','Status','select',employee?['Review requested']:['Proposed','Approved','Review requested'])],r,p=>api('/resources/kpis/'+id,'PATCH',p));return;}
if(act==='report-feedback'){const r=await resourceRecord('reports',id);const employee=state.boot.user.role==='employee';formModal(employee?'Request review':'Reviewer feedback',employee?[]:[simpleField('feedback','Reviewer feedback','textarea'),simpleField('status','Status','select',['Reviewed','Correction requested'])],r,p=>api('/resources/reports/'+id,'PATCH',employee?{status:'Correction requested'}:p));return;}
if(act==='candidate-stage'){const r=await resourceRecord('candidates',id);formModal('Move stage',[simpleField('stage','Status','select',['New','Screening','Shortlisted','Interview','Evaluation','Offer','Hired','Rejected'])],r,p=>api('/resources/candidates/'+id,'PATCH',p));return;}
if(act==='interview-feedback'){const r=await resourceRecord('interviews',id);formModal('Feedback',[simpleField('skill_score','Skill score','number'),simpleField('communication_score','Communication score','number'),simpleField('feedback','Feedback','textarea'),simpleField('status','Status','select',['Scheduled','Completed','Cancelled'])],r,p=>api('/resources/interviews/'+id,'PATCH',p));return;}
if(act==='upload'){if(el.dataset.candidate){state.candidates=await api('/resources/candidates');return uploadForm(true);}return uploadForm();}
if(act==='download'){window.location.assign('/api/documents/'+id);return;}
if(act==='print'){window.print();return;}
if(act==='submit-case')return submitCase();
if(act==='track-case')return trackCase();
if(act==='case-detail')return caseDetail(id);
if(act==='download-case'){downloadText(el.dataset.ref+'.txt',`${t('Case reference')}: ${el.dataset.ref}\n${t('Follow-up token')}: ${el.dataset.token}\nKeep this file private.`);return;}
if(act==='survey')return showSurvey(id);
if(act==='survey-results')return surveyResults(id);
if(act==='offboarding'){if(el.dataset.status==='Submitted'){formModal('Acknowledge',[],{},()=>api('/resignations/'+id,'POST',{action:'acknowledge'}),'Acknowledge',`<p>${state.lang==='ar'?'إقرار الاستقالة وإنشاء قائمة إنهاء الخدمة؟':'Acknowledge this resignation and create the offboarding checklist?'}</p>`);}else{formModal('Complete offboarding',[simpleField('exit_interview','Exit interview','textarea'),simpleField('settlement','Settlement reviewed','select',['Reviewed'])],{},p=>api('/resignations/'+id,'POST',{...p,action:'complete'}),'Complete offboarding',`<p class="danger-note">${state.lang==='ar'?'يُؤرشف الموظف ويُغلق الوصول بعد إتمام القائمة ومراجعة التسوية.':'This archives the employee and closes access after checklist completion and settlement review.'}</p>`);}return;}
if(act==='provision'){formModal('Create user account',[simpleField('employee_id','Employee name','employee'),simpleField('role','Role','select',['employee','leader','manager','hr','owner']),simpleField('password','New password','password')],{employee_id:id||''},p=>api('/accounts','POST',p));return;}
if(act==='leave-type'){formModal('Add request type',[simpleField('name','Name'),simpleField('deduct_balance','Deduct annual balance','checkbox',null,false),simpleField('payroll_factor','Unpaid fraction (0–1)','number'),simpleField('unit','Unit','select',['days','hours'])],{payroll_factor:0},p=>api('/leave-types','POST',p));return;}
if(act==='notifications')return notifications();
if(act==='read-notifications'){const result=await api('/notifications','POST',{});toast(result.message);closeModal();return;}
if(act==='agent'){state.agent=el.dataset.agent;renderAssistant();return;}
if(act==='suggestion')return sendMessage(state.lang==='ar'?(el.dataset.message.includes('balance')?'ما هو رصيد إجازاتي؟':'اقترح تدريباً للفجوات في المهارات'):el.dataset.message);
if(act==='ai-prompt')return aiPrompt(el.dataset.agent);
if(act==='job-description'){formModal('Generate job description',[simpleField('title','Job title'),simpleField('skills','Required skills')],{},async p=>{const result=await api('/ai','POST',{agent:'recruitment',message:'Generate a job description for '+p.title+'. Required skills: '+p.skills});modal('Generate job description',`<div class="info-strip">${esc(result.disclosure)} ${t('Review required')}</div><textarea class="field-input" id="generated-jd" rows="14">${esc(result.answer)}</textarea><p class="helper">${state.lang==='ar'?'راجع وعدّل الوصف ثم استخدمه عند إنشاء وظيفة جديدة.':'Review and edit this draft, then use it when creating a new vacancy.'}</p>`,button('Copy','copy-jd')+button('Close','close-modal'));return {keepOpen:true};},'Generate job description');return;}
if(act==='copy-jd'){await navigator.clipboard.writeText($('#generated-jd').value);toast(t('Copy'));return;}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();Promise.resolve(action(el)).catch(error=>toast(error.message,true));});
document.addEventListener('change',async e=>{if(!e.target.matches('[data-check-id]'))return;const input=e.target;input.disabled=true;try{await api('/resources/checklists/'+input.dataset.checkId,'PATCH',{done:input.checked});toast(t('Save changes'));await loadPage();}catch(error){input.checked=!input.checked;toast(error.message,true);}finally{input.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.modal'))closeModal();if(e.key==='Tab'&&$('.modal')){const focusable=$$('button,input,textarea,select,a[href]',$('.modal')).filter(x=>!x.disabled);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
