const baseRenderDashboard=renderDashboard;
renderDashboard=function(d){baseRenderDashboard(d);const role=state.boot.user.role;const panel=document.createElement('div');panel.className='grid-main';const alerts=d.contract_alerts||[];const training=d.next_training;let left=`<section class="panel"><div class="panel-head"><h2>${t('Your priorities')}</h2>${icon('check')}</div><div class="notice-list"><div class="notice"><div class="notice-icon">${icon('book')}</div><div><h3>${t('Training session')}</h3><p>${training?esc(training.title)+' · '+day(training.session_at,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):t('No scheduled training')}</p></div></div><div class="notice"><div class="notice-icon">${icon('folder')}</div><div><h3>${t('Contract alerts')}</h3><p>${d.contract_alert_count} ${t('Review required')}</p>${alerts.slice(0,4).map(a=>`<p>${esc(person(a.employee_id))} · ${day(a.end)}</p>`).join('')}</div></div></div></section>`;let right='';if(['owner','hr'].includes(role)){right=`<section class="panel"><div class="panel-head"><h2>${t('Payroll status')}</h2>${icon('wallet')}</div><div class="notice-list"><div class="notice"><div><h3>${t('Basic salary')} · ${t('Active workforce')}</h3><p>${currency(d.payroll_total_cents)}</p></div></div>${(d.payroll_status||[]).map(p=>`<div class="notice"><div><h3>${p.month} · ${badge(p.status)}</h3><p>${p.count} ${t('records')} · ${currency(p.total_cents)}</p></div></div>`).join('')}<div class="notice"><div><h3>${t('Recruitment pipeline')}</h3><p>${d.recruitment.map(c=>t(c.stage)+': '+c.count).join(' · ')||t('No records yet')}</p></div></div></div></section>`;}else{right=`<section class="panel"><div class="panel-head"><h2>${t('My requests')}</h2>${icon('calendar')}</div><div class="panel-pad"><div class="stat-number">${d.leave_balance} <small>${t('days available')}</small></div><p class="small-text muted">${d.pending} ${t('Pending requests')}</p>${button('Request time off','create','data-table="leave_requests"','primary small')}</div></section>`;}panel.innerHTML=left+right;$('.page-footer').before(panel);};
const baseRenderResource=renderResource;
renderResource=async function(){await baseRenderResource();const page=state.page;const additions={employees:[['employees','People'],['positions','Job positions']],kpis:[['kpis','Performance'],['kpi_templates','KPI library'],['performance-trends','Performance trends']],learning_plans:[['employee_skills','Skill assessments'],['training-impact','Training impact']],leave_requests:[['attendance-exceptions','Attendance exceptions']],resignations:[['workforce-trends','Workforce trends']],announcements:[['announcements','Company home'],['calendar','Calendar']]};let nav=$('.tabs');if(additions[page]){if(!nav){nav=document.createElement('div');nav.className='tabs';$('.filters').before(nav);}for(const [key,label] of additions[page]){if($(`[data-tab="${key}"]`,nav))continue;nav.insertAdjacentHTML('beforeend',`<button class="tab ${key===(state.tab||page)?'active':''}" data-action="tab" data-tab="${key}">${t(label)}</button>`);}}
const acts=$('.page-heading .actions');if(page==='kpis'&&['hr','manager','leader'].includes(state.boot.user.role))acts.insertAdjacentHTML('beforeend',button('Apply role KPIs','apply-templates'));if(page==='tasks'&&canCreate('tasks'))acts.insertAdjacentHTML('beforeend',button('Assign to team','assign-team'));if(page==='kpis'||page==='reports')acts.insertAdjacentHTML('beforeend',button('Comment on evaluation','performance-comment'));};
const baseRenderTab=renderTab;
renderTab=async function(){const table=state.tab||state.page;const root=$('#records');const special=['attendance-exceptions','performance-trends','training-impact','workforce-trends','calendar'];if(!special.includes(table))return baseRenderTab();$('#sub-actions').innerHTML='';state.viewData=[];state.viewTable=table;
if(table==='attendance-exceptions'){const r=await api('/attendance-report');root.innerHTML=`<div class="info-strip">${state.lang==='ar'?'مؤشرات للمراجعة البشرية فقط. لا تفرض خصومات تلقائية. يُحسب الغياب من الأيام المجدولة المنتهية دون حضور أو إجازة معتمدة خلال آخر ٣٠ يوماً.':'Review indicators only; no automatic penalties. Missing attendance uses completed scheduled workdays without check-ins or approved day leave over the past 30 days.'}</div><div class="panel table-wrap"><table><thead><tr>${['Employee name','Late days','Absence indicators','Early days','Overtime'].map(l=>`<th>${t(l)}</th>`).join('')}</tr></thead><tbody>${r.indicators.map(i=>`<tr><td>${esc(person(i.employee_id))}</td><td>${i.late_days}</td><td>${i.absence_indicators}</td><td>${i.early_days}</td><td>${i.overtime_hours}h</td></tr>`).join('')}</tbody></table></div>`;}
if(table==='performance-trends'){const r=await api('/performance-insights');root.innerHTML=`<div class="cards-grid">${r.periods.map(p=>`<div class="panel record-card"><h3>${esc(p.period)}</h3><div class="stat-number">${p.score===null?'—':p.score+'%'}</div><p>${p.objectives} ${t('Objective / KPI')}</p></div>`).join('')}</div><section class="panel panel-pad"><h2>${t('Monthly reports')}</h2><p class="small-text">${r.report_months.join(' · ')||t('No data for this period')}</p><h2>${t('Comment on evaluation')}</h2>${r.notes.length?r.notes.map(n=>`<div class="notice"><div><h3>${esc(person(n.employee_id))} ${n.request_correction?badge('Correction requested'):''}</h3><p>${esc(n.comment)}</p><small>${day(n.created_at)}</small></div></div>`).join(''):empty()}</section>`;}
if(table==='training-impact'){const r=await api('/training');root.innerHTML=r.length?`<div class="info-strip">${state.lang==='ar'?'تغيّر التقييم والمؤشرات يصف النتائج المسجلة ولا يثبت أن التدريب وحده سبب التحسن.':'Assessment and KPI changes describe recorded outcomes; they do not establish that training alone caused improvement.'}</div><div class="panel table-wrap"><table><thead><tr>${['Employee name','Course','Progress','Assessment change','KPI change','Attendance days','Practical application','Actions'].map(l=>`<th>${t(l)}</th>`).join('')}</tr></thead><tbody>${r.map(p=>`<tr><td>${esc(person(p.employee_id))}</td><td>${esc(p.course)}</td><td>${p.progress}%</td><td>${p.assessment_change??'—'}</td><td>${p.kpi_change??'—'}</td><td>${p.attendance.filter(a=>a.attended).length}</td><td>${esc(p.practical_application||'—')}</td><td>${button('Record training attendance','training-attendance',`data-id="${p.plan_id}"`,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty();}
if(table==='workforce-trends'){if(state.boot.user.role==='employee'){root.innerHTML=empty();return;}const r=await api('/workforce');root.innerHTML=`<div class="stats-grid">${stat('Average tenure',r.average_tenure_years+' '+t('years'),'Active workforce','users')}${stat('Replacement estimate',currency(r.replacement_cost_estimate_cents),'Review required','wallet')}</div><div class="info-strip">${esc(r.replacement_assumption)}</div><section class="panel table-wrap"><table><thead><tr>${['Month','Headcount','Departures','Turnover rate'].map(l=>`<th>${t(l)}</th>`).join('')}</tr></thead><tbody>${r.periods.map(p=>`<tr><td>${p.month}</td><td>${p.headcount}</td><td>${p.departures}</td><td>${p.turnover_percent}%</td></tr>`).join('')}</tbody></table></section><section class="panel panel-pad"><h2>${t('Department')}</h2>${r.departments.map(d=>`<p class="small-text">${esc(d.department)} · ${d.employees} ${t('People')} · ${d.departures_12m} ${t('Departures')} (12m)</p>`).join('')}<h2>${t('Reason')}</h2>${Object.entries(r.resignation_themes).map(([k,v])=>`<p class="small-text">${esc(k)}: ${v}</p>`).join('')||t('No records yet')}</section>`;}
if(table==='calendar'){const events=state.data.filter(a=>a.event_date&&a.status==='Published').sort((a,b)=>a.event_date.localeCompare(b.event_date));state.calendarEvents=events;$('#sub-actions').innerHTML=button('Download calendar','calendar-download','','small');root.innerHTML=events.length?`<section class="panel panel-pad">${events.map(a=>`<div class="notice"><div class="calendar-day"><b>${day(a.event_date,{day:'numeric'})}</b><small>${day(a.event_date,{month:'short'})}</small></div><div><h3>${esc(a.title)}</h3><p>${esc(a.content)}</p><small>${day(a.event_date,{weekday:'long',year:'numeric',month:'long',day:'numeric'})}</small></div></div>`).join('')}</section>`:empty();}
};
const baseRowActions=rowActions;
rowActions=function(r,table){let html=baseRowActions(r,table);if(table==='candidates'&&state.boot.user.role==='hr'&&!r.employee_id){html+=button('Hire & onboard','hire',`data-id="${r.id}"`,'small primary');}return html;};
Object.assign(ar,{'Hire & onboard':'توظيف وتهيئة','Approval history':'سجل الموافقات','Approver':'المعتمد','Decision':'القرار'});
const baseSurveyResults=surveyResults;
surveyResults=async function(id){await baseSurveyResults(id);const r=await api('/surveys/'+id);if(!r.suppressed){$('.modal-body').insertAdjacentHTML('beforeend',`<div class="info-strip">${state.lang==='ar'?'تحليل تجريبي قائم على القواعد للنتائج المجمعة':'Demo rule-based analysis of aggregates'}: ${esc(r.sentiment)}<br>${Object.entries(r.themes).filter(([,v])=>v>0).map(([k,v])=>esc(t(k))+': '+v).join(' · ')}</div>`);}};
caseDetail=function(id){const r=state.data.find(r=>r.id===Number(id));formModal('Case owner',[simpleField('owner_id','Case owner','handler'),simpleField('status','Status','select',['Open','In review','Awaiting information','Resolved','Closed']),simpleField('category','Category','select',['General','Workload','Communication','Work environment','Payroll','Conduct']),simpleField('due','Due date','date'),simpleField('resolution','Resolution','textarea',null,false),simpleField('message','Follow-up message','textarea',null,false)],{...r,owner_id:r.owner_id||state.boot.user.id},p=>api('/cases','POST',{...p,id:r.id,action:'update'}),'Save',`<h3>${esc(r.title)} · ${esc(r.case_ref)}</h3><p class="detail-content">${esc(r.detail)}</p><p class="helper">${t(r.anonymous?'Anonymous':'Identified')}</p><div class="timeline">${(r.history||[]).map(h=>`<p><small>${day(h.created_day)} · ${esc(h.author)}</small>${esc(h.message)}</p>`).join('')}</div>`);};
const baseAction=action;
action=async function(el){const act=el.dataset.action;const id=Number(el.dataset.id);if(act==='apply-templates'){formModal('Apply role KPIs',[simpleField('employee_id','Employee name','employee'),simpleField('period_id','Evaluation period','period',null,false)],{},p=>api('/apply-kpi-templates','POST',p));return;}
if(act==='performance-comment'){formModal('Comment on evaluation',[simpleField('employee_id','Employee name','employee'),simpleField('comment','Comment','textarea'),simpleField('request_correction','Request correction','checkbox',null,false)],{employee_id:state.boot.user.employee_id},p=>api('/performance-notes','POST',p));return;}
if(act==='assign-team'){const fields=state.boot.catalog.tasks.fields.filter(f=>f.name!=='employee_id').map(f=>f.name==='team_id'?{...f,required:true}:f);formModal('Assign to team',fields,{complexity:3,estimated_hours:4},p=>api('/assign-team','POST',p));return;}
if(act==='training-attendance'){formModal('Record training attendance',[simpleField('day','Date','date'),simpleField('attended','Attended','checkbox',null,false),simpleField('notes','Notes','textarea',null,false)],{attended:true},p=>api('/training','POST',{...p,plan_id:id}));return;}
if(act==='calendar-download'){const safe=s=>String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,c=>'\\'+c);const body=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Northstar//People//EN',...(state.calendarEvents||[]).flatMap(a=>['BEGIN:VEVENT','UID:northstar-'+a.id+'@demo.local','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;VALUE=DATE:'+a.event_date.replaceAll('-',''),'SUMMARY:'+safe(a.title),'DESCRIPTION:'+safe(a.content),'END:VEVENT']),'END:VCALENDAR'].join('\r\n');downloadText('northstar-calendar.ics',body,'text/calendar');return;}
if(act==='learning-progress'){const r=await resourceRecord('learning_plans',id);formModal('Update progress',[simpleField('progress','Progress','number'),simpleField('post_score','Post-assessment (0–100)','number'),simpleField('application','Practical application','textarea',null,false),simpleField('session_at','Training session','datetime-local',null,false),simpleField('baseline_kpi','KPI before training','number'),simpleField('followup_kpi','KPI after training','number')],r,p=>api('/resources/learning_plans/'+id,'PATCH',p));return;}
if(act==='hire'){const c=await resourceRecord('candidates',id);const jobs=await api('/resources/jobs');const job=jobs.find(j=>j.id===c.job_id);const fields=state.boot.catalog.employees.fields.filter(f=>['team_id','manager_id','leader_id','employment_type','work_mode','joined','salary_cents','annual_days'].includes(f.name));formModal('Hire & onboard',fields,{team_id:job.department_id,employment_type:'Full time',work_mode:'Office',salary_cents:2500000,annual_days:21},p=>api('/candidates/'+id+'/hire','POST',p),'Hire & onboard',`<h3>${esc(c.name)} · ${esc(job.title)}</h3><p class="small-text">${state.lang==='ar'?'هذا قرار توظيف بشري. يُنشأ سجل موظف وقائمة تهيئة مشتركة مع بقية الوحدات.':'This is a human hiring decision. It creates the shared employee record and onboarding checklist.'}</p>`);return;}
if(act==='view'&&(el.dataset.table||state.viewTable)==='leave_requests'){const r=await resourceRecord('leave_requests',id);const h=await api('/leave/'+id+'/history');modal('Approval history',recordDetails(r,'leave_requests')+`<h3>${t('Approval history')}</h3>${h.steps.map(s=>`<p class="small-text">${s.ordinal+1}. ${esc(person(s.approver_id))} · ${badge(s.status)}</p>`).join('')}<div class="timeline">${h.decisions.map(d=>`<p><small>${day(d.created_at)} · ${esc(d.actor)}</small>${esc(d.decision)} · ${esc(d.reason)}</p>`).join('')}</div>`,null,true);return;}
return baseAction(el);};
